package com.orderflow.delivery.config;import io.micrometer.core.instrument.MeterRegistry;import java.util.Map;import org.apache.kafka.clients.admin.*;import org.apache.kafka.common.TopicPartition;import org.springframework.boot.actuate.health.*;import org.springframework.context.annotation.*;import org.springframework.kafka.config.TopicBuilder;import org.springframework.kafka.core.*;import org.springframework.kafka.listener.*;import org.springframework.util.backoff.FixedBackOff;
@Configuration public class KafkaConfiguration{@Bean NewTopic deliveryTopic(KafkaTopicProperties p){return TopicBuilder.name(p.deliveryEvents()).partitions(3).replicas(1).build();}@Bean NewTopic deliveryDlt(KafkaTopicProperties p){return TopicBuilder.name(p.deliveryEventsDlt()).partitions(3).replicas(1).build();}@Bean DefaultErrorHandler deliveryKafkaErrorHandler(KafkaTemplate<String,String>t,KafkaTopicProperties p,MeterRegistry m){DeadLetterPublishingRecoverer r=new DeadLetterPublishingRecoverer(t,(record,e)->{m.counter("orderflow_kafka_dlt_publications_total","service","delivery-service").increment();return new TopicPartition(p.deliveryEventsDlt(),record.partition());});DefaultErrorHandler h=new DefaultErrorHandler(r,new FixedBackOff(500,2));h.setCommitRecovered(true);return h;}@Bean HealthIndicator kafkaHealthIndicator(KafkaAdmin a){Map<String,Object>c=a.getConfigurationProperties();return()->{try(AdminClient x=AdminClient.create(c)){x.listTopics().names().get();return Health.up().build();}catch(Exception e){return Health.down().build();}};}}
